    "CARACTERÍSTICAS": "Permite segmentar audiencias y automatizar envíos según el comportamiento del usuario; tiene uno de los mejores retornos de inversión del marketing digital. Limitación: tasas de apertura y entrega bajas si la base de contactos no está bien depurada o el contenido se percibe como spam.",
