    "CARACTERÍSTICAS": "Se apoya fuertemente en email marketing y marketing automation; busca mover al lead de una etapa del embudo a la siguiente. Limitación: un nurturing demasiado lento o genérico puede hacer que el lead pierda interés antes de llegar a la decisión de compra.",
