    "CARACTERÍSTICAS": "Se apoya en SEO, blogs, redes sociales y email marketing; busca construir relaciones a largo plazo en lugar de ventas inmediatas. Limitación: requiere más tiempo para mostrar resultados que las estrategias de marketing directo o pagado.",
