    "CARACTERÍSTICAS": "Genera resultados más rápidos e inmediatos que el inbound marketing; suele tener un costo por contacto más alto. Limitación: las personas tienden a percibirlo como más invasivo, lo que puede generar rechazo si no está bien segmentado.",
