    "CARACTERÍSTICAS": "Puede usar perfiles de gran alcance (macroinfluencers) o de nicho con alta cercanía con su audiencia (microinfluencers). Limitación: la efectividad depende mucho de la afinidad real entre el influencer y la marca; una mala selección puede dañar la credibilidad de ambos.",
