    "CARACTERÍSTICAS": "El pago se realiza solo cuando se cumple el resultado esperado (venta, registro, etc.), lo que reduce el riesgo para el anunciante. Limitación: requiere un sistema confiable de seguimiento de enlaces para atribuir correctamente cada conversión al afiliado correspondiente.",
