    "CARACTERÍSTICAS": "Permite tomar decisiones basadas en datos en lugar de suposiciones; se debe cambiar una sola variable a la vez para que el resultado sea confiable. Limitación: necesita un volumen de tráfico suficiente para que los resultados tengan significancia estadística real.",
