    "CARACTERÍSTICAS": "Permite personalizar mensajes y mejorar la eficiencia de la inversión publicitaria; puede basarse en criterios demográficos, geográficos, conductuales o psicográficos. Limitación: una segmentación demasiado amplia diluye el mensaje, mientras una demasiado estrecha puede limitar el alcance de la campaña.",
