    "CARACTERÍSTICAS": "Es un indicador de la calidad de la relación con la audiencia, más allá del simple alcance; varía según la plataforma y el tipo de contenido. Limitación: un alto engagement no siempre se traduce directamente en ventas o conversiones reales para el negocio.",
