    "CARACTERÍSTICAS": "Se compara frecuentemente con el valor de vida del cliente (LTV) para evaluar la sostenibilidad del modelo de negocio. Limitación: un CAC bajo aislado no dice mucho si no se analiza junto al LTV; un cliente barato de adquirir pero que compra poco puede no ser rentable.",
