    "CARACTERÍSTICAS": "Es una métrica crítica en negocios SaaS y de suscripción; un churn alto puede anular el crecimiento generado por la captación de nuevos clientes. Limitación: no diferencia por sí sola entre las distintas razones de cancelación, por lo que requiere un análisis adicional para identificar causas.",
