    "CARACTERÍSTICAS": "Se aplica en anuncios, landing pages, correos y CTAs; busca equilibrio entre persuasión y honestidad. Limitación: un copywriting demasiado agresivo o exagerado puede generar desconfianza y dañar la reputación de la marca a largo plazo.",
