    "CARACTERÍSTICAS": "Funciona como una notificación HTTP automática (push) en lugar de una consulta constante (polling); es clave para integrar sistemas como pagos o mensajería. Limitación: si el sistema receptor está caído en el momento del envío, el evento puede perderse si no existe un mecanismo de reintento.",
