    "CARACTERÍSTICAS": "Los contenedores son más ligeros que las máquinas virtuales tradicionales porque comparten el mismo sistema operativo base. Limitación: requiere una curva de aprendizaje adicional para configurar correctamente imágenes y volúmenes de datos.",
