    "CARACTERÍSTICAS": "Permite reiniciar automáticamente contenedores caídos y distribuir la carga entre servidores; es el estándar de la industria para sistemas a gran escala. Limitación: su complejidad de configuración suele ser excesiva para proyectos pequeños o de bajo tráfico.",
