    "CARACTERÍSTICAS": "A diferencia de un framework, no impone una estructura al proyecto: el desarrollador decide cuándo y cómo usarla. Limitación: depender de demasiadas librerías externas aumenta el riesgo de seguridad y de mantenimiento si alguna deja de actualizarse.",
