    "CARACTERÍSTICAS": "Se gestionan a través de archivos como package.json; pueden tener a su vez sus propias dependencias (dependencias transitivas). Limitación: tener demasiadas dependencias, o desactualizadas, aumenta el riesgo de vulnerabilidades de seguridad en el proyecto.",
