    "CARACTERÍSTICAS": "Es el estilo de API más utilizado actualmente por su simplicidad y compatibilidad con HTTP; cada recurso se representa generalmente en formato JSON. Limitación: en sistemas con relaciones de datos muy complejas, REST puede requerir múltiples llamadas para obtener toda la información necesaria.",
    "ENTORNO": "Desarrollo de software, APIs",
