    "CARACTERÍSTICAS": "Reduce el problema de pedir datos de más o de menos (over-fetching y under-fetching); requiere un esquema bien definido del lado del servidor. Limitación: su flexibilidad puede dificultar el almacenamiento en caché de respuestas, en comparación con una API REST tradicional.",
