    "CARACTERÍSTICAS": "Es fácil de leer tanto para humanos como para máquinas; es el formato estándar de respuesta en la mayoría de las APIs REST modernas. Limitación: a diferencia de XML, JSON no soporta comentarios dentro del propio archivo, lo que dificulta documentarlo directamente.",
