    "CARACTERÍSTICAS": "Mejora el SEO y el tiempo de carga inicial percibido, ya que el HTML ya viene completo desde el servidor. Limitación: genera más carga de procesamiento en el servidor que una aplicación que renderiza todo del lado del cliente.",
