    "CARACTERÍSTICAS": "Combina las ventajas de una página web (sin necesidad de tiendas de aplicaciones) con funcionalidades antes exclusivas de apps nativas. Limitación: algunas funciones avanzadas del dispositivo (como ciertos sensores) tienen soporte limitado comparado con una aplicación nativa real.",
