    "CARACTERÍSTICAS": "Puede implementarse a nivel de navegador, servidor o CDN; mejora significativamente la velocidad de carga percibida. Limitación: una caché desactualizada (datos viejos) puede mostrarle al usuario información que ya no corresponde a la realidad.",
