    "CARACTERÍSTICAS": "Puede ser simétrica (una sola clave) o asimétrica (clave pública y privada); es la base de protocolos como HTTPS. Limitación: una encriptación fuerte no protege los datos si la clave utilizada se gestiona o almacena de forma insegura.",
