    "CARACTERÍSTICAS": "Cada etiqueta HTML se convierte en un nodo dentro de este árbol; manipular el DOM directamente permite cambios dinámicos sin recargar la página. Limitación: manipular el DOM de forma excesiva o ineficiente puede afectar negativamente el rendimiento de una página, especialmente en dispositivos de gama baja.",
