    "CARACTERÍSTICAS": "Se compila (transpila) hacia JavaScript estándar antes de ejecutarse en el navegador; mejora la mantenibilidad en proyectos grandes. Limitación: agrega un paso adicional de compilación y una curva de aprendizaje extra para equipos acostumbrados solo a JavaScript.",
