    "CARACTERÍSTICAS": "Suele incluir minificación, eliminación de código no usado y división de código en partes (code splitting); ejemplos comunes son Webpack y Vite. Limitación: una mala configuración del bundler puede generar archivos finales innecesariamente pesados, afectando la velocidad de carga.",
