    "CARACTERÍSTICAS": "Es el bloque fundamental de construcción en frameworks como React o Vue; favorece la reutilización y el mantenimiento del código. Limitación: dividir una interfaz en demasiados componentes pequeños sin un criterio claro puede dificultar entender el flujo general de la aplicación.",
