    "CARACTERÍSTICAS": "Los más usados son useState (para manejar estado) y useEffect (para ejecutar acciones tras un cambio); simplificó enormemente la escritura de componentes en React. Limitación: existen reglas estrictas sobre dónde y cómo se pueden usar los hooks, y romperlas genera errores difíciles de diagnosticar.",
