    "CARACTERÍSTICAS": "Fluyen en una sola dirección (de padre a hijo), lo que facilita predecir cómo se comporta la aplicación. Limitación: pasar props a través de muchos niveles de componentes anidados ('prop drilling') puede volver el código difícil de mantener.",
