    "CARACTERÍSTICAS": "Fácil de usar con interfaz visual; integración nativa con Excel, Word y otros productos Microsoft; soporta macros y VBA para automatización. Limitación: tamaño máximo de base de datos de 2 GB; máximo 255 conexiones simultáneas; no apto para entornos web ni móvil; seguridad débil comparada con alternativas enterprise; no cumple GDPR de forma nativa; rendimiento degradado con grandes volúmenes de datos.",
