    "CARACTERÍSTICAS": "Permiten persistencia, integridad y acceso concurrente a la información. Existen de distintos tipos: relacionales (SQL), documentales, de grafos, clave-valor y en tiempo real. Limitación: una mala arquitectura de datos genera inconsistencias, duplicidades y problemas de rendimiento difíciles de corregir en producción.",
