    "CARACTERÍSTICAS": "Sincronización de datos en tiempo real entre clientes; escalable con la infraestructura de Google Cloud; fácil integración con Android, iOS y web; plan gratuito disponible (Spark). Limitación: no soporta consultas SQL complejas; vendor lock-in con Google; costos impredecibles a escala; no permite acceso a nivel de servidor; las consultas en Realtime Database son limitadas (un solo índice por consulta); migración de datos compleja por uso de JSON.",
