    "TRADUCCIÓN / EQUIVALENCIA": "MySQL / My Structured Query Language / Open source relational database",
    "EJEMPLOS": "WordPress, Joomla, Drupal; la mayoría de hostings compartidos usan MySQL por defecto",
    "CATEGORÍA": "Bases de Datos",
