    "CARACTERÍSTICAS": "Máxima robustez y confiabilidad en entornos de misión crítica; soporte para transacciones ACID complejas a escala masiva; herramientas avanzadas de auditoría, cifrado y particionamiento; soporte multi-nodo con Oracle RAC. Limitación: licenciamiento extremadamente costoso (puede superar los $50,000 por procesador); alta complejidad de administración; requiere DBA especializado; no apto para proyectos pequeños o medianos por costo y overhead.",
    "ENTORNO": "Banca, gobierno, telecomunicaciones, sector salud, grandes corporaciones",
