    "CARACTERÍSTICAS": "Totalmente ACID-compliant; soporte nativo de JSONB con indexación GIN; extensiones poderosas como PostGIS (geoespacial), pgvector (IA/ML) y TimescaleDB (series temporales); implementación de MVCC superior para alta concurrencia; el más popular entre desarrolladores según Stack Overflow 2024-2025. Limitación: mayor complejidad de configuración que MySQL; tooling GUI nativo (pgAdmin) menos pulido que SSMS de SQL Server; mayor consumo de recursos por proceso por conexión.",
    "ENTORNO": "Aplicaciones modernas, ciencia de datos, IA/ML, SaaS, geoespacial, fintech",
    "ENTRADA / PROCESO / SALIDA": "Entrada (queries SQL avanzadas, JSON, datos geoespaciales) → Proceso (planificador de queries, extensiones, MVCC) → Salida (datos complejos, análisis, reportes avanzados)",
    "TRADUCCIÓN / EQUIVALENCIA": "PostgreSQL / Postgres / Object-relational database / Base de datos objeto-relacional",
