    "CARACTERÍSTICAS": "Integración nativa con Azure, Power BI y el ecosistema Microsoft; herramientas GUI potentes como SQL Server Management Studio (SSMS); soporte para Always On Availability Groups para alta disponibilidad; excelente para data warehousing con SSIS y SSAS. Limitación: licenciamiento costoso (hasta $15,000+ por procesador en edición Enterprise); principalmente orientado a Windows aunque tiene versión Linux; vendor lock-in con Microsoft; menos popular entre developers independientes que PostgreSQL.",
