    "CARACTERÍSTICAS": "Cero configuración y administración; archivo único portátil (.db o .sqlite); soporte completo de SQL estándar; ideal para aplicaciones embebidas, móviles y prototipado rápido; presente en iOS, Android, Firefox y millones de apps. Limitación: no apto para múltiples escrituras concurrentes (bloqueos a nivel de archivo); sin soporte para usuarios, roles ni permisos; no escala para aplicaciones de alta concurrencia o grandes volúmenes; no soporta JSON nativo ni tipos avanzados.",
