    "CARACTERÍSTICAS": "No es un lenguaje de programación sino de marcado; define estructura, no estilo. HTML5 (versión actual) añade soporte nativo para audio, video, canvas y semántica avanzada. Compatible con todos los navegadores modernos. Limitación: por sí solo no tiene interactividad ni estilos visuales — requiere CSS y JavaScript para completar la experiencia.",
    "ENTORNO": "Desarrollo web, frontend, navegadores, diseño digital",
