    "CARACTERÍSTICAS": "Sistema de cascada y especificidad para resolver conflictos de estilos; soporte para variables CSS (custom properties), Grid, Flexbox, animaciones y media queries para responsive design. Limitación: la especificidad puede volverse compleja en proyectos grandes; no tiene lógica condicional nativa (requiere preprocesadores como Sass o frameworks como Tailwind).",
    "ENTORNO": "Frontend, diseño web, UI, responsive design",
