    "CARACTERÍSTICAS": "Arquitectura basada en componentes; Virtual DOM para renderizado eficiente; unidireccionalidad del flujo de datos; ecosistema enorme (Next.js, React Native, Redux). Limitación: curva de aprendizaje inicial; solo maneja la capa de vista (requiere librerías adicionales para estado global, routing, etc.); actualizaciones frecuentes pueden romper compatibilidad.",
    "ENTORNO": "Frontend, aplicaciones web SPA, aplicaciones móviles (React Native)",
