    "CARACTERÍSTICAS": "Integración nativa con productos Microsoft; más de 60 regiones globales; soporte sólido para entornos híbridos (on-premise + cloud); herramientas avanzadas de IA con Azure OpenAI Service. Limitación: interfaz más compleja que AWS para algunos servicios; costos de licencias Microsoft se suman al costo cloud; curva de aprendizaje alta.",
    "ENTORNO": "Empresas Microsoft, .NET, DevOps enterprise, BI, inteligencia artificial",
