    "CARACTERÍSTICAS": "Capacidad de generalizar a partir de datos; mejora continua con más datos de entrenamiento; tipos principales: supervisado, no supervisado y por refuerzo; herramientas clave: TensorFlow, PyTorch, Scikit-learn. Limitación: requiere grandes volúmenes de datos de calidad; los modelos son cajas negras difíciles de explicar (interpretabilidad); puede aprender y amplificar sesgos de los datos de entrenamiento.",
    "ENTORNO": "Inteligencia artificial, ciencia de datos, automatización, productos digitales",
