    "CARACTERÍSTICAS": "Automatiza tareas cognitivas complejas; mejora con el tiempo gracias al aprendizaje; aplicable en casi todos los sectores (salud, finanzas, educación, marketing). Limitación: sesgos en datos de entrenamiento generan resultados discriminatorios; consumo energético alto para modelos grandes; riesgo de desplazamiento laboral; falta de transparencia en modelos complejos.",
