    "CARACTERÍSTICAS": "Requiere infraestructura especializada (Hadoop, Spark, BigQuery); permite descubrir patrones ocultos en enormes volúmenes de datos; base del análisis predictivo y la IA empresarial. Limitación: alto costo de infraestructura; requiere equipos especializados (data engineers, data scientists); privacidad y seguridad de datos crítica; no todos los problemas de negocio requieren Big Data.",
    "ENTORNO": "Ciencia de datos, negocios, gobierno, marketing, salud, telecomunicaciones",
