    "CARACTERÍSTICAS": "Alta similitud visual con el producto final; permite al cliente ver exactamente cómo se verá el producto; base para el handoff al desarrollador. Limitación: no interactivo (no se puede hacer clic ni navegar); cambios tardíos en mockup aún pueden requerir reprogramación costosa.",
    "ENTORNO": "Diseño UI, agencias creativas, presentaciones a clientes, desarrollo web",
