    "TRADUCCIÓN / EQUIVALENCIA": "Design System / Sistema de diseño / Component library",
    "EJEMPLOS": "El styles.css y los componentes del portfolio Vladisystems son una forma básica de design system",
    "CATEGORÍA": "UI / UX",
    "NIVEL TÉCNICO": "Intermedio"
