    "CARACTERÍSTICAS": "Gestión de múltiples plataformas simultáneamente; requiere habilidades de redacción, diseño básico y análisis de datos; capacidad de respuesta rápida ante crisis de reputación online. Limitación: a menudo confundido con el Social Media Manager (el CM es más operativo, el SMM más estratégico); burnout frecuente por disponibilidad constante.",
